do $stage46$
declare changes jsonb:='[{"id":"d1430000-0000-4000-8000-000000000044","label":"M44","beforeHash":"f81c50ffaea348f43111fee2edc732e159ea8fb32559793f4ee2d2efd5a3ef79","afterHash":"e17ee435f53ba59f404f86f0f4e3788156a010f5dd1c5b1fdf77a465f7c7c911","patch":{"difficulty":"hard","statement":"Dez trabalhadores realizariam uma tarefa em doze dias de seis horas. Após quatro dias nesse ritmo, a tarefa precisa ser concluída nos seis dias seguintes, com jornadas de quatro horas. A produtividade individual é constante e não há interferência entre trabalhadores. Quantos trabalhadores deve ter a equipe nessa segunda etapa?","options":["10 trabalhadores","30 trabalhadores","20 trabalhadores","18 trabalhadores","15 trabalhadores"],"explanation":"A tarefa exige 10 × 12 × 6 = 720 trabalhador-horas. A primeira etapa realiza 10 × 4 × 6 = 240, restando 480. Cada trabalhador da segunda etapa fornece 6 × 4 = 24 horas; são necessários 480/24 = 20 trabalhadores.","version":3}},{"id":"d1430000-0000-4000-8000-000000000064","label":"M64","beforeHash":"502e0d73c1db100827c489909bb791dd95f7a07541fc228200804ec2bc31f157","afterHash":"3356d5ae98664343e78597773b7fd239988070cca2a36420641709fe74570a7a","patch":{"difficulty":"hard","statement":"Doze trabalhadores realizam uma tarefa em doze dias de seis horas. Em tarefa idêntica, uma equipe de dezoito trabalha seis horas por dia, mas cada trabalhador produz 20% menos por hora. Não há interferência entre trabalhadores e a produtividade fica constante em cada equipe. Em quantos dias a segunda equipe termina a tarefa?","options":["8 dias","9 dias","15 dias","10 dias","12 dias"],"explanation":"A carga equivalente é 12 × 12 × 6 = 864 horas da produtividade inicial. A segunda equipe realiza por dia 18 × 6 × 0,8 = 86,4 horas equivalentes. Logo, precisa de 864/86,4 = 10 dias. Considerar somente o aumento de trabalhadores daria oito dias e ignoraria a produtividade menor.","version":3}},{"id":"d1430000-0000-4000-8000-000000000082","label":"M82","beforeHash":"74f816658fedb76cb64424982037782354df76dd117783a0e41cc8613ac8e355","afterHash":"833886360f358d4f344720d3f481b8e0a26a3e15fe1d1076fe17a5c8bebff3b1","patch":{"statement":"Um produto recebeu aumento de 20%. A loja pretende devolver o preço ao valor inicial, aplicando um desconto sobre o preço reajustado. Qual análise determina o desconto necessário?","version":3}},{"id":"d1430000-0000-4000-8000-000000000083","label":"M83","beforeHash":"938ffc60e545073d38e2cd1259c7f82a57ecd547b21b76006eecab3b685382f7","afterHash":"2a0fafbbe2d410196c9c5544c5938e627c41b3619355db3fd1673dde7dfebdae","patch":{"statement":"Duas lojas têm o mesmo preço de tabela P, superior a R$ 25. Uma oferece desconto de 25%; a outra, abatimento de R$ 25. Em que situação a oferta percentual é mais barata?","version":3}},{"id":"d1430000-0000-4000-8000-000000000095","label":"M95","beforeHash":"c33978ae367cc0bd17e03a988fe80d10b45328c38b64da2ed2a91eb1c43629b9","afterHash":"b1b0babf2a95cae55b381968bce5c8486d58f8deb77c15591888be33e797a96c","patch":{"options":["Fica quatro vezes maior, pois a capacidade varia com o quadrado do comprimento.","Permanece igual, pois a largura e a altura não mudaram.","Aumenta apenas dois litros, independentemente das medidas originais.","Dobra, pois apenas uma das três dimensões foi multiplicada por dois.","Fica oito vezes maior, como se as três dimensões tivessem dobrado."],"version":3}},{"id":"d1430000-0000-4000-8000-000000000097","label":"M97","beforeHash":"d0bff9d0b22b1610f256582c2632f70ad6724b35ba42f9756583b485ea6df496","afterHash":"79eaaf0ce9398fed784d5b3468e39794645379f8d988116c765aa487532e9e8b","patch":{"options":["40° é o ângulo externo; o interno mede 180° − 40° = 140°.","40° é o interno, pois os ângulos internos de qualquer polígono somam 360°.","O interno mede 180°/9 = 20°, pois os nove ângulos internos somam 180°.","O interno mede 40°/9, pois ainda é necessário dividir pelos lados.","O interno mede 360° − 40° = 320°."],"version":4}},{"id":"d1430000-0000-4000-8000-000000000098","label":"M98","beforeHash":"14ca52afc6193d4c5022aa9ca6be09ba53ec3a1824299e2c55102dadfa8a2405","afterHash":"9302d7e02e069baf41f9812f6a5072ae69a08e8b4e3823a5f0029a26f48e3ed8","patch":{"statement":"Entre oito pessoas, duas serão escolhidas para uma comissão sem cargos distintos. Por que 8 × 7 precisa ser dividido por dois?","version":4}},{"id":"d1431000-0000-4000-8000-000000000075","label":"P75","beforeHash":"7c0bfb22b20c0b467e65dfe92b0b5dc2f8423e7eb3676e37d01d430b2bbb5ace","afterHash":"7bac997e1cbfc4178012662095d0062b6f2d3794d4ab33fdd6de77bbffdc8116","patch":{"statement":"A turma viu um documentário e depois o debateu. Uma revisora quer retomar “o documentário” por uma oração relativa com o verbo assistir no sentido de ver.\n\nQual frase respeita a regência desse verbo na norma-padrão adotada pelo Manual de Comunicação do Senado?","explanation":"No sentido de ver ou presenciar, assistir exige a preposição a na norma-padrão adotada. Ao usar que para retomar documentário, a preposição vem antes do relativo: “o documentário a que os estudantes assistiram”. As demais opções substituem essa preposição ou empregam cujo sem relação de posse.","version":4}},{"id":"d1431000-0000-4000-8000-000000000077","label":"P77","beforeHash":"56bedaea7f719ac49c87be6624a80e1e9dfd69c3f81c6776bf316463e7945e2a","afterHash":"df0a7eb13baf037c2f7e206b0710f53a928fa9a1b688c58407d706b21a8fafc7","patch":{"statement":"A frase “A professora informou à aluna que sua inscrição estava incompleta” permite leituras diferentes do possessivo. O redator sabe que a inscrição pertence à aluna.\n\nQual reescrita explicita esse referente, preservando a informação sobre o estado da inscrição?","explanation":"A expressão “a inscrição da aluna” identifica explicitamente a pessoa a quem a inscrição pertence. Trocar informou por comunicou mantém o possessivo ambíguo; dela e aquela não nomeiam a proprietária. Sua própria também não explicita, nessa construção, que a inscrição é da aluna.","version":4}},{"id":"d1390000-0000-4000-8000-000000000004","label":"C06","beforeHash":"abed75e82301eb40db1f611a879c8ac603f2e4a60c0ad04f4689cbfc2c0dc516","afterHash":"0d95df97bc62496b41c50a579df95d5def42c41a6b415cd98ad2ec2b44948c84","patch":{"statement":"Quatro ramos da mesma espécie aquática, com áreas foliares equivalentes e em condições semelhantes de saúde, são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nQue comparação permite avaliar o efeito da intensidade luminosa mantendo as outras condições descritas?","version":6}},{"id":"d1390000-0000-4000-8000-000000000014","label":"C16","beforeHash":"b58e87634a5800b4a9b5430803088f816ab12733bc0d36ede58e3fc1b2476d53","afterHash":"0f1c60bd3d30e3b08b70e458d649e2ba00f4e956365a6d42c5f44cd009a9c932","patch":{"statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro, com iguais volumes de ar, umidade e temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nQue inferência é compatível com a comparação entre os frascos?","version":5}},{"id":"d1390000-0000-4000-8000-000000000016","label":"C18","beforeHash":"09fc1defb0fca56262af2d22acd57700dd8cb2fa1f151b28b2f57e75bebfaa0b","afterHash":"94e3ee43a34ff0b16bd38699d961f88638e54f403dc3dd2a5f80d0ce8a21896e","patch":{"statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. O cultivo permaneceu fechado, sem entrada ou saída de indivíduos.\n\nQue leitura distingue esse crescimento de uma duplicação indefinida?","version":5}},{"id":"d1390000-0000-4000-8000-000000000018","label":"C20","beforeHash":"0177586e6fa34759bb92be5ff76f7bb1d683da6819c1735692ac1f7f6239e5bd","afterHash":"0e20b7139af1e777c65d1cd3ed1294c51962acdd24da494c8bd9e48080832477","patch":{"statement":"Duas caixas de mesma geometria, diferentes apenas no material de revestimento, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nPor que a caixa revestida de espuma conserva mais gelo nas condições do experimento?","version":6}},{"id":"d1432000-0000-4000-8000-000000000026","label":"C26","beforeHash":"af7e16a277d128f87cdb3b6a12016cb9090d6dc666441d59e6a17d27f0ecb89d","afterHash":"ce307eb4b0620749c3169281171380534ed51f15cbabfdcb8b9af62e0b617ba4","patch":{"statement":"Quatro ramos da mesma espécie aquática, com áreas foliares equivalentes e em condições semelhantes de saúde, são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nQue interpretação é sustentada pela comparação entre A e C?","version":4}},{"id":"d1432000-0000-4000-8000-000000000036","label":"C36","beforeHash":"1877c94ac25b9af49bba249c4c95b62a34875e3d00bf79e6ce3186ea214a4c6f","afterHash":"856bf1e10a172487419782eda82212a7fa7974a64033300ed5051a70babe0904","patch":{"statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro, com iguais volumes de ar, umidade e temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nQual redução relativa da concentração de oxigênio ocorre em A, tomando 21% como referência inicial?","version":3}},{"id":"d1432000-0000-4000-8000-000000000038","label":"C38","beforeHash":"b586886154955eee274b82c764c7917a4cb07518ceeb3ff6c50637f1ee57f0a7","afterHash":"6e296b594e3e817514bd773e18fb6cbe9d2d97e39feb572296a13ad2ba9e1256","patch":{"statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. O cultivo permaneceu fechado, sem entrada ou saída de indivíduos.\n\nQual crescimento relativo ocorre de 200 para 320 indivíduos?","version":3}},{"id":"d1432000-0000-4000-8000-000000000040","label":"C40","beforeHash":"145197902343daca83c91162aa42ebf1856bb6b6675a8d1d72cea0536725d197","afterHash":"2200c9c963e72948b7bc2f6080d19da9f307cb6101b945f5efd2b2afd8405e66","patch":{"statement":"Duas caixas de mesma geometria, diferentes apenas no material de revestimento, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nQual variável deve permanecer comparável para atribuir a diferença ao revestimento?","version":4}},{"id":"d1432000-0000-4000-8000-000000000046","label":"C46","beforeHash":"d56247369c8e6b6a8811390fb3a4029010fbb77feb0a0b0840e8277220f53e10","afterHash":"5ed035b349995108576cf3f1e44aa9458e1b653dbd82b7925b46af8c5d305971","patch":{"statement":"Quatro ramos da mesma espécie aquática, com áreas foliares equivalentes e em condições semelhantes de saúde, são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nA ausência de bolhas em D permite concluir o quê, sem extrapolar o indicador?","version":4}},{"id":"d1432000-0000-4000-8000-000000000051","label":"C51","beforeHash":"4116f2b0c2b0304b632c5f60ce2a562037c82ada79f28bc2b9272eace606859d","afterHash":"d36892cda0996233d445825a6eb5a551c6c003bbf809d1da2eac716d0de2af23","patch":{"options":["Permanece em 20 g/L, pois restam 9 g em 450 mL.","Sobe para 60 g/L, pois a retirada reverte a diluição anterior.","Sobe para 26,7 g/L, pois sai água, mas se considera que todo o soluto permanece.","Cai para 5 g/L, pois passa a um quarto da concentração inicial.","Cai para 15 g/L, pois sai um quarto do soluto e o volume é considerado constante."],"version":3}},{"id":"d1432000-0000-4000-8000-000000000056","label":"C56","beforeHash":"85d14da3fadf466b6ced50a0723f20f25624f8752134fd10fb3e2b51b04106ab","afterHash":"a3ff70088f853917d82bfdcb39974bf053d7e43b7b12f71e1d6a2f3e8b63e2ed","patch":{"statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro, com iguais volumes de ar, umidade e temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nPor que o frasco B é relevante para a interpretação?","version":3}},{"id":"d1432000-0000-4000-8000-000000000058","label":"C58","beforeHash":"f2a4d7f7c0300e711cc1712f23b93e75ec91a3f44b3be745fe5ad54ed4913c0c","afterHash":"992c49f0fbe9cb52acbdba3120c0f99e637e73321b63962259375e979ec41f25","patch":{"statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. O cultivo permaneceu fechado, sem entrada ou saída de indivíduos.\n\nQue mudança pode alterar o patamar próximo de 400?","version":3}},{"id":"d1432000-0000-4000-8000-000000000060","label":"C60","beforeHash":"9962b971241cf260b58ddef8f8a0e34b886f890700587f387e424ee6d619cbd2","afterHash":"e482731a8563400ef64c03f3dee4ec7dfde8202b15109770357a982fca5faaa1","patch":{"statement":"Duas caixas de mesma geometria, diferentes apenas no material de revestimento, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nSe o conteúdo estivesse quente e o ambiente frio, qual previsão sobre a espuma seria coerente?","version":4}},{"id":"d1432000-0000-4000-8000-000000000066","label":"C66","beforeHash":"e4ae047b46f0571802133ac54f0d4db2c41f10b5cf83d3f9de571323760f2d23","afterHash":"f73d6409e1db1477163b250a2e8d464a8c62f582343a2d1af8b932811b883dbd","patch":{"statement":"Quatro ramos da mesma espécie aquática, com áreas foliares equivalentes e em condições semelhantes de saúde, são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nQual razão entre as contagens de A e B resume o resultado, sem afirmar precisão sobre a massa de oxigênio?","version":4}},{"id":"d1432000-0000-4000-8000-000000000072","label":"C72","beforeHash":"869fdb5ee1361e10f631860d611b92c510636d2975672095c62f93a64e769dee","afterHash":"d9ff6ac12373d49461173dd370b821bba79c70202d6a9b774cc37766ecc92836","patch":{"statement":"Ao misturar bicarbonato de sódio e solução ácida, uma análise identifica consumo de reagentes e formação de substâncias diferentes, incluindo gás carbônico. Em outro teste, apenas a água de uma solução evapora, sendo recuperada por condensação.\n\nQue critério distingue a reação química da mudança de estado nesses testes?","explanation":"A identificação de substâncias diferentes, associada ao consumo dos reagentes, caracteriza a transformação química. Na evaporação e condensação, a água muda de estado, preservando sua identidade química. Bolhas ou mudanças de massa isoladas não bastam para distinguir os processos.","version":3}},{"id":"d1432000-0000-4000-8000-000000000076","label":"C76","beforeHash":"2a529b673106d880da534ec69891e20950578e7facafb3d14088aca5b89d9e68","afterHash":"25b4450943e4cb12251e61824a8c560b6b52acb020b7bd8f55cbf1259a059b93","patch":{"statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro, com iguais volumes de ar, umidade e temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nQue resultado adicional seria coerente com respiração aeróbia no frasco A?","version":3}},{"id":"d1432000-0000-4000-8000-000000000078","label":"C78","beforeHash":"fc5f90aa3cc3793bab547799bd5af23964fe1ce3fc2f9b9f0131145328e9c4b7","afterHash":"c6bd72cd7cd61eba61620ce0a45ce71b3d229cbbd26d76c1b0ba612463084060","patch":{"statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. O cultivo permaneceu fechado, sem entrada ou saída de indivíduos.\n\nQual resultado pode produzir estabilidade em torno de 400 mesmo com reprodução contínua?","options":["Nascimentos e mortes aproximadamente equilibrados ao longo dos períodos.","Aumento do alimento, que reduziria o patamar por diminuir a competição.","Mudança do intervalo de registro, sem alterar recursos nem interações.","Redução do espaço, que elevaria o patamar por aproximar os indivíduos.","Aumento apenas do número inicial, que tornaria ilimitados os recursos disponíveis."],"version":3}},{"id":"d1432000-0000-4000-8000-000000000080","label":"C80","beforeHash":"eb998913c11a470bf1e47d4201a1586996fe83bb1aa87a80bd2861def0be4daa","afterHash":"4ce82c410da4376ff8716501c4bc8ffc8f62be7ce18e31f9b831bbced8121ecc","patch":{"statement":"Duas caixas de mesma geometria, diferentes apenas no material de revestimento, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nQue observação impediria concluir que B não recebeu calor durante o teste?","version":4}},{"id":"d1432000-0000-4000-8000-000000000086","label":"C86","beforeHash":"b3f65394e48fe55efc2aacaf4b1d9e5b095e128bc7bafbdde16b2bdce08251e3","afterHash":"75ab28509f57ffdc40e8f6755c66aad02883e33cc7e40dc177019c68356cfd7c","patch":{"statement":"Quatro ramos da mesma espécie aquática, com áreas foliares equivalentes e em condições semelhantes de saúde, são mantidos em frascos com igual volume de água e temperatura. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido em relação aos demais; D fica no escuro. A, B e D têm a mesma concentração inicial de gás carbônico. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.\n\nComo melhorar a confiabilidade da conclusão sobre intensidade luminosa?","version":4}},{"id":"d1432000-0000-4000-8000-000000000096","label":"C96","beforeHash":"aebdbd321c6f2e60f4b14ac526e9b6384468636149d1972944b4c666afbc0911","afterHash":"59e5bcde8c33e0fc87a45f39f28999f91bcbe1ef6a2419ff20bfa87f089498c1","patch":{"statement":"Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro, com iguais volumes de ar, umidade e temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.\n\nSe A estivesse aberto e recebesse ar continuamente, que dificuldade surgiria?","version":3}},{"id":"d1432000-0000-4000-8000-000000000098","label":"C98","beforeHash":"15c62a0c96f02b64227f1449e68f50d81ec4d6d06557560e553942b9b8ff0ec5","afterHash":"ab83a5c3a9ae7d5f2d36d049559378258c5a1e8d629c2e5f7db7b05d4f309236","patch":{"statement":"Em um cultivo com espaço e alimento limitados, em intervalos de mesma duração, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. O cultivo permaneceu fechado, sem entrada ou saída de indivíduos.\n\nQual informação adicional ajuda a investigar o mecanismo da desaceleração?","options":["Medir alimento disponível por indivíduo e taxas de nascimento e morte em cada intervalo.","Interrupção de todos os nascimentos, com manutenção da mortalidade.","Mortes persistentemente maiores que os nascimentos, sem outra mudança.","Ausência de mortes, com manutenção contínua dos nascimentos.","Nascimentos persistentemente maiores que as mortes, sem outra mudança."],"version":3}},{"id":"d1432000-0000-4000-8000-000000000100","label":"C100","beforeHash":"beef035914653ea3783cba5a27966e99f993853cab5a0eca7d8041a991582c41","afterHash":"08f27da80ad0f24973fd68efb3ebddf96bed23fa47b90a838c4beaf890c8a10d","patch":{"statement":"Duas caixas de mesma geometria, diferentes apenas no material de revestimento, com mesma quantidade de gelo e temperatura inicial de 0 °C, são colocadas em um ambiente a 25 °C. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final.\n\nSe os dois conteúdos forem observados por tempo suficiente no mesmo ambiente, sem fontes ativas, o que se espera em termos de tendência térmica?","version":4}},{"id":"d1433000-0000-4000-8000-000000000041","label":"H41","beforeHash":"a063ba6e21aa2c260495f3e964a68b91d46bea8273ca7aacdd73bb0bf741c735","afterHash":"0f1c8704b00c44588907fd600bd13f4946a2ad5515eeb08de7915b53c2cae8d0","patch":{"statement":"Em uma escavação fictícia, um recipiente isolado contém grãos. Em outra área do mesmo sítio e período, encontram-se instrumentos com marcas de corte de cereais e restos de estruturas de armazenamento.\n\nQue diferença existe entre as duas bases de evidência para estudar o cultivo?","options":["O conjunto de vestígios fortalece a hipótese de produção e armazenamento locais, que o recipiente isolado não demonstrava.","A presença de armazenamento exclui a circulação de grãos por troca entre grupos.","As marcas de corte permitem concluir que todos os habitantes trabalhavam exclusivamente no cultivo.","Os dois conjuntos demonstram a mesma organização social, pois ambos contêm grãos.","O recipiente isolado permite datar o início do cultivo com mais precisão que o conjunto contextualizado."],"explanation":"Restos associados no espaço e no período permitem relacionar processamento e armazenamento, fortalecendo uma hipótese que um objeto isolado não demonstra. Isso não estabelece exclusividade agrícola, igualdade social nem ausência de trocas.","version":3}},{"id":"d1433000-0000-4000-8000-000000000043","label":"H43","beforeHash":"04ceb7f7f4a5ac5200b91ef504a4cd08f99baf6b8329e06549c5f0fd350131b9","afterHash":"ac720439f84923551021554bd3e79e0e3113bf11798b95d9bd5a6ed067a43603","patch":{"statement":"Em um exercício sobre a República romana, dois registros descrevem o mesmo território após conquistas: grandes proprietários ampliam suas terras e empregam mais pessoas escravizadas; pequenos produtores endividados perdem lotes durante ausências militares prolongadas.\n\nComo os registros ajudam a explicar tensões internas ligadas à expansão?","options":["O aumento de terras controladas por grandes proprietários demonstra que todos os pequenos produtores receberam lotes equivalentes.","Os recursos das conquistas e as condições do serviço militar podiam beneficiar e prejudicar grupos diferentes.","O emprego de pessoas escravizadas indica que os proprietários deixaram de disputar terras.","As perdas dos pequenos produtores significam que não houve ampliação territorial romana.","A participação em campanhas militares garantia a conservação da propriedade dos combatentes."],"explanation":"A expansão territorial e a distribuição interna de seus efeitos são dimensões diferentes. Os registros combinam concentração de terras com vulnerabilidade dos pequenos produtores; não indicam divisão igual dos ganhos nem segurança automática da propriedade de soldados.","version":3}},{"id":"d1433000-0000-4000-8000-000000000045","label":"H45","beforeHash":"bc2f796aa70a69da1c18b80f4c56e4dd9f16a3e00ab4c4618bbe100fcd277774","afterHash":"589dee2958372fe06580a90a1ba9276555cdd20786789195c1423faac47bcb6d","patch":{"statement":"Uma atividade apresenta duas edições fictícias de uma gravura do século XVI. Ambas usam a mesma imagem, mas as legendas atribuem sentidos opostos à cena. O impressor e o público de destino também mudaram entre as edições.\n\nQual interpretação considera a relação entre técnica de reprodução e circulação de ideias?","options":["O significado da gravura depende apenas do desenho, tornando as legendas dispensáveis à análise.","O emprego da mesma imagem comprova que as duas edições se destinavam ao mesmo público.","As legendas opostas demonstram que as imagens não podiam ser reproduzidas por impressão.","A mudança de impressor basta para concluir que uma das edições foi produzida antes da invenção da imprensa.","Reproduzir a mesma imagem não assegura a mesma mensagem, pois legenda e contexto de circulação orientam sua leitura."],"explanation":"A reprodução permite reutilizar uma imagem em contextos distintos. Legendas, autoria editorial e destinatários integram o material analisado e podem alterar a mensagem. Identidade visual não comprova identidade de público ou intenção.","version":3}},{"id":"d1433000-0000-4000-8000-000000000046","label":"H46","beforeHash":"d55b2e487bd96d92f3becc6e15b4d10f9d36a90d3972699219d2952e9785fea8","afterHash":"391cf2a95a9d0f9406f2aefce0ad24ba8b295fd5348bd2054549da1e0a6b6f71","patch":{"statement":"Em uma atividade sobre as reformas religiosas do século XVI, dois textos didáticos fictícios defendem posições diferentes. O texto A apresenta as Escrituras como autoridade suficiente para a doutrina; o B também reconhece a tradição e a autoridade da Igreja.\n\nQual aspecto do conflito os textos permitem comparar diretamente?","options":["A decisão de ambos os autores de abandonar qualquer texto religioso.","A ausência de divergências doutrinárias, pois ambos mencionam as Escrituras.","A identidade de posição entre os autores quanto ao papel da tradição.","O apoio dos dois autores ao mesmo governante, deduzido apenas das referências às Escrituras.","Os critérios usados para reconhecer a autoridade religiosa e fundamentar a doutrina."],"explanation":"Os textos diferem nas fontes de autoridade que reconhecem. Compartilhar uma referência não elimina a divergência sobre a tradição e a Igreja. Não foram apresentados dados que identifiquem alianças políticas ou permitam atribuir essas posições a todas as correntes reformadoras.","version":3}},{"id":"d1433000-0000-4000-8000-000000000048","label":"H48","beforeHash":"b7eb820b7527e87146c4fc84cb626082749b8b76099876799785d9e74d81d364","afterHash":"f8587f1e4b18c42ffc6a57253ae0ae34a7f2ba2a4d96289aa8a9a15d072ca1b8","patch":{"statement":"Para estudar um engenho colonial, uma atividade cruza dois registros fictícios do mesmo ano: a contabilidade aponta aumento das vendas de açúcar; uma ordem administrativa restringe deslocamentos de trabalhadores escravizados e prevê punições.\n\nQue leitura articula os registros sem confundir produção com condições de trabalho?","options":["O crescimento das vendas podia coexistir com coerção, e a contabilidade sozinha não descreve a experiência dos trabalhadores.","A ordem de punição permite calcular o valor exportado sem consultar a contabilidade.","O aumento das vendas demonstra que as restrições aos trabalhadores deixaram de ser aplicadas.","As vendas elevadas comprovam que os trabalhadores recebiam a receita na mesma proporção que o proprietário.","A presença de uma ordem escrita transforma o trabalho escravizado em contrato livre."],"explanation":"Os registros tratam de aspectos diferentes e compatíveis: circulação de mercadorias e controle do trabalho. Receita não mede liberdade, remuneração ou distribuição. A ordem pode informar práticas de coerção, mas não substitui os dados de vendas.","version":3}},{"id":"d1433000-0000-4000-8000-000000000049","label":"H49","beforeHash":"7382859064ba945a8d7c43f361b11d32742aea1c9dd2fcfab96376c4419889f4","afterHash":"eeeca591ea10dd7c0caa7aab4d0662d54cd49e46e2b97bc741dc9e66c7974207","patch":{"statement":"Em uma atividade sobre uma zona mineradora colonial, um registro fictício mostra aumento do ouro extraído e outro registra aumento do preço da farinha no mesmo período. Não há dados de salários, estoques ou número de moradores.\n\nQual conclusão respeita o alcance das duas informações?","options":["A expansão da extração coexistiu com encarecimento do abastecimento, sem comprovar melhoria de vida de todos os grupos.","Os dois aumentos permitem calcular exatamente o salário real dos trabalhadores.","A alta da farinha comprova que a região deixou de produzir qualquer alimento.","A coincidência temporal demonstra que os tributos foram a única causa do encarecimento da farinha.","A alta do ouro demonstra que a renda de todos cresceu mais que o preço da farinha."],"explanation":"As duas séries descrevem mudanças de extração e de preço. Sem renda, oferta e demanda, não se calcula poder de compra nem se isola uma causa do encarecimento. Expansão econômica agregada não demonstra benefício uniforme.","version":3}},{"id":"d1433000-0000-4000-8000-000000000051","label":"H51","beforeHash":"5151155658fb59629173e033ab789359af111bad67da104e0d771165331d7085","afterHash":"4d101e1ac04823fd698ab2ddae3be18e8ec011943b810e9eb02af5756dd55751","patch":{"statement":"Uma fábrica fictícia do período de industrialização tem cem trabalhadores. Antes, produzia mil peças por dia em jornadas de dez horas; depois, passou a produzir mil e quinhentas em jornadas de doze horas. O quadro de trabalhadores ficou igual e não há dados de salários.\n\nQue comparação distingue aumento de produção e condições de trabalho?","options":["A produção diária e a jornada cresceram na mesma proporção, de 50%.","O aumento da jornada explica integralmente a alta de produção, mantendo a produção por hora exatamente igual.","A produção maior demonstra que a jornada individual foi reduzida pela metade.","A manutenção do número de trabalhadores comprova que o salário de cada um cresceu 50%.","A produção diária cresceu 50% e a jornada, 20%; esses dados não demonstram aumento de salário ou de tempo livre."],"explanation":"A produção passou de 1.000 a 1.500: aumento de 50%. A jornada passou de 10 a 12 horas: aumento de 20%. Com o mesmo quadro, a produção por trabalhador-hora também cresceu, de 1 para 1,25 peça. Nenhum desses resultados informa salário ou redução da jornada.","version":3}},{"id":"d1433000-0000-4000-8000-000000000053","label":"H53","beforeHash":"effd6d3b0ba6b5815375c3ede5a791a7012fe732eafbe543c05dcd825784dea7","afterHash":"2dc79a8d5a1cd6f5efd8207f2f13ffb84d8624b45523acd081c88adb50499f06","patch":{"statement":"Dois projetos fictícios de um movimento de independência defendem romper com a metrópole. O projeto A mantém a exigência de renda para votar; o B propõe ampliar a participação para homens livres sem essa exigência. Ambos preservam a concentração de terras.\n\nQual comparação distingue consenso pela ruptura e divergências sobre o novo Estado?","options":["A defesa comum da independência coexistia com projetos distintos de participação política e uma continuidade na propriedade.","A manutenção das grandes propriedades significa que nenhum dos projetos defendia ruptura política.","A proposta B estabelece participação política de todos os habitantes, sem qualquer exclusão.","A proposta A prevê distribuição de terras porque exige renda para votar.","A mesma posição sobre a metrópole implica propostas idênticas de cidadania."],"explanation":"O ponto comum é romper o vínculo metropolitano, não adotar a mesma cidadania. B amplia o grupo proposto em relação a A, mas ainda o limita a homens livres. Ambos mantêm a concentração de terras, permitindo distinguir dimensões da mudança.","version":3}},{"id":"d1433000-0000-4000-8000-000000000056","label":"H56","beforeHash":"1dde2fd1693eb17ce223cdfa7d55afca4c4fbb1c81ff01eef9f413ebe7845451","afterHash":"6bd01f24af2b42871d59de959b1fd3d9c23ca8a561404966a46daef151ec89f0","patch":{"statement":"Uma atividade sobre o Brasil após 1888 compara dois registros fictícios de 1890: um contrato prevê salário para uma pessoa emancipada; uma petição de trabalhadores reclama de barreiras ao acesso à escola e à moradia. Não há informação sobre distribuição de terras.\n\nQue análise considera conjuntamente os registros?","options":["A referência a direitos na petição demonstra que as reivindicações já haviam sido integralmente atendidas.","O contrato assalariado demonstra que todos os emancipados receberam terras.","A mudança jurídica e o trabalho remunerado podiam coexistir com desigualdades no acesso a direitos e condições de vida.","A petição comprova que a lei de abolição manteve juridicamente a escravidão.","O contrato permite concluir que não existiam barreiras sociais para quem recebia salário."],"explanation":"O contrato indica uma relação remunerada, enquanto a petição registra reivindicações sociais não resolvidas. Liberdade jurídica não implica acesso igual a escola e moradia. Os documentos não demonstram distribuição de terras nem manutenção legal da escravidão.","version":3}},{"id":"d1433000-0000-4000-8000-000000000058","label":"H58","beforeHash":"a8016d86a9e5db73f9b0ed63d61c86e756f7695be03da20f268c6429502dba2d","afterHash":"9659ed93d3458199430775fc4f79f5a33f18b9315a1d183c452cf08532561557","patch":{"statement":"Uma atividade reúne duas cartas fictícias do mesmo soldado na Primeira Guerra: em 1914, ele espera voltar para casa em poucas semanas; em 1916, descreve o prolongamento do combate e dificuldades de abastecimento.\n\nComo interpretar a diferença entre os dois relatos?","options":["As dificuldades relatadas em 1916 demonstram que já eram conhecidas com a mesma intensidade em 1914.","A carta de 1916 invalida a de 1914 como fonte, porque expectativas não podem ser estudadas historicamente.","A expectativa de retorno rápido comprova que a guerra terminou em 1914 para todos os países.","Ela permite comparar uma expectativa inicial com uma experiência posterior, sem transformar a primeira expectativa em descrição do desfecho.","A autoria comum garante que os relatos descrevem todas as frentes da guerra e todas as experiências civis."],"explanation":"Uma fonte pode registrar expectativas que não se concretizam. A passagem do tempo e o prolongamento do combate ajudam a interpretar a mudança de perspectiva. A autoria comum não torna o testemunho universal nem permite ler o futuro como se fosse conhecido em 1914.","version":3}},{"id":"d1433000-0000-4000-8000-000000000096","label":"H96","beforeHash":"3f9a0683915dd763d9b8a1f7ed038b2169b454b36bd4300c6ed917f48a2e24ea","afterHash":"e871b540f6a9b918925765725f160e4d149e89bf3438484ca734a4b745d529bc","patch":{"statement":"Uma linha do tempo indica a independência brasileira em 1822, a abolição legal da escravidão em 1888 e a proclamação da República em 1889.\n\nQual afirmação NÃO é sustentada por esses marcos?","explanation":"A cronologia situa 1888 após a independência e antes da República, ainda no Império. A abolição extinguiu a condição legal de escravidão, mas esses marcos não demonstram distribuição de terras nem igualdade de renda. Para estudar essas condições, são necessárias outras evidências.","version":3}},{"id":"d1394000-0000-4000-8000-000000000003","label":"G05","beforeHash":"1dd5431fbb5cedf1a2d75c8b1e45c8fcabe3794b2452954e96f1fc2093e31c08","afterHash":"bc19f4dc40cc79f4f54ebce91cbfd74bbb28daf1f6787a27e43a92eddddf7560","patch":{"statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. A razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nQual é a razão de dependência demográfica aproximada?","version":5}},{"id":"d1394000-0000-4000-8000-000000000006","label":"G08","beforeHash":"0f38694db67b61e0658b1a709cedb38d1635b562e2e076fdd67ca3c639f0e69a","afterHash":"1e47ec2ba716384fc36fb18f5b7ef95e32403a8c6c6afbeed3b956a477f427b7","patch":{"statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. Nas dez horas do período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. Potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQue potências médias resultam no período?","version":5}},{"id":"d1394000-0000-4000-8000-000000000011","label":"G13","beforeHash":"d040fc1fe3292d3cbccf20d7a16714cf26d585afe4032bbd62e907e5d00e1b6c","afterHash":"0ea362f0ecfa633c966d23738b9d62df44356422a205287925845430346ca95f","patch":{"statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. Saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nQual comparação dos saldos está correta?","version":5}},{"id":"d1394000-0000-4000-8000-000000000015","label":"G17","beforeHash":"0472396e83a27982dc8c5f6e24b86e84705dab8c08dc342886ed381f14ad7b2e","afterHash":"c8f1c0f555099b97f31a25cc901cec19c763d4b3ded09312202434ca19faa886","patch":{"statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. Considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nQual comparação das coordenadas é correta?","version":5}},{"id":"d1394000-0000-4000-8000-000000000016","label":"G18","beforeHash":"7def7930196bbbcdef12532333ff918f78d669bec36cc88f73bcafa7ba136c29","afterHash":"6cce0e2c045b47dbc2fc2ee54c16f8fda9d02b104dcccc0501b9a263d5d67c1a","patch":{"statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. Força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nQual taxa de desocupação resulta da definição fornecida?","version":5}},{"id":"d1434000-0000-4000-8000-000000000025","label":"G25","beforeHash":"15d8bbc7515641c8de09d567692bfa57d3d138dd4bb3335c5513f7a8d3525cc4","afterHash":"cef84fd51dd2517bf3bc3dffdd35992255e5ca5390ed8dcc5cb716798c010a64","patch":{"statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. A razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nQue fração da população total tem 65 anos ou mais?","version":3}},{"id":"d1434000-0000-4000-8000-000000000028","label":"G28","beforeHash":"a6c5d6c306033c87dc266f2bb42948094b18367d9ab43fed2364e7e30491e660","afterHash":"16bd56630a16db5558bb487cbece365ef5807bf4d0e882f2687a24c3d6a3d57b","patch":{"statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. Nas dez horas do período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. Potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQual energia total as duas fontes produziram nas dez horas observadas?","version":3}},{"id":"d1434000-0000-4000-8000-000000000033","label":"G33","beforeHash":"b90faa1a3cdbf1d738f1b4b18b1f60735ba515e0df1a9beb5df20b780269add9","afterHash":"936aca8a463b4e3f8c7a532c08cee39e18c827f6b5faac51195a05e2cc88d552","patch":{"statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. Saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nSe julho recebesse irrigação de 50 mm, qual saldo simplificado passaria a ter?","version":3}},{"id":"d1434000-0000-4000-8000-000000000037","label":"G37","beforeHash":"567a8b6d6b9cddad7aaa90e8d12a09a579dd631bfab813efd1e47da95cbb5aa9","afterHash":"db7243f3f5f75aed20ac8b1e80601aa1908a6bfe0508cb8ebd2b0dd3a34f4647","patch":{"statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. Considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nQual separação angular de latitude existe entre A e B?","version":3}},{"id":"d1434000-0000-4000-8000-000000000038","label":"G38","beforeHash":"ec7068a1606f2f05ff3f4ace8bea1ffb2a6a6a39518097e05d7423c974dad392","afterHash":"84fd2e5d8bf7321d0e9d5454db46b6ca1cd31bf6ceb12b197325889d23a2575d","patch":{"statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. Força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nSe 1.000 desocupados conseguirem trabalho e ninguém mudar de grupo de participação, qual será a nova taxa?","version":3}},{"id":"d1434000-0000-4000-8000-000000000045","label":"G45","beforeHash":"20b1073ca12dc0dad62bb147841aa7ab5474ee517f8b269d8842fd07f7b4e171","afterHash":"eae216efd830147a63b251537b3b40c07ceb52d2c76fe5a55a0f317915c9acc0","patch":{"statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. A razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nPor que não se pode transformar diretamente a razão calculada em desemprego?","version":3}},{"id":"d1434000-0000-4000-8000-000000000048","label":"G48","beforeHash":"e87f0f594b4db3685cae434c24529b8197fe51de148221e0fca5871bcb201bc4","afterHash":"9dee858ab77ad9450a523fc69dacdce07d78323ee61cf3deb4e307e0c941a56f","patch":{"statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. Nas dez horas do período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. Potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQual participação aproximada da geração solar no total médio das duas fontes?","version":3}},{"id":"d1434000-0000-4000-8000-000000000053","label":"G53","beforeHash":"b3fd67aec1b706757547901850b5b3269e0e0b334347a286cb56e8e62c44d822","afterHash":"d934495e7fc78c88602c51e8dfcbbf27aa82a27a63cf303e7fc4c33c547ade00","patch":{"statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. Saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nQue informação falta para transformar esse saldo em diagnóstico completo de disponibilidade de água para plantas?","version":3}},{"id":"d1434000-0000-4000-8000-000000000057","label":"G57","beforeHash":"ba62c0be679dffaf22e51a4f4bf755ea8e6c2c9ded21e702950768418de595e8","afterHash":"7c4671f1fdd268a05fdbefdb30e4fee964cc4e3eebc6b78de77926378d107ab3","patch":{"statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. Considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nEm relação a A, C está em que direção sobre o paralelo indicado?","version":3}},{"id":"d1434000-0000-4000-8000-000000000058","label":"G58","beforeHash":"c8c74bf3ce2da6d53bf35fa620360e715bc229b5eedb6f8d1ee2c06530941606","afterHash":"32fdeb7b94d8a211db7a3a0f149d3215e9f460e21a41dce2cb17a31bb2bbda45","patch":{"statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. Força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nSe 1.000 desocupados deixarem de procurar trabalho e saírem da força, sem conseguir emprego, qual taxa resulta?","version":3}},{"id":"d1434000-0000-4000-8000-000000000065","label":"G65","beforeHash":"934a7f4e13b654a36d8aa6458b4b0c4a49c30626cc5e6f018f10da2e82308ef6","afterHash":"0002b2b5031cbeae314a5b86a0ada6d4694b935b60f27f662161e376c015e2e1","patch":{"statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. A razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nSe o grupo de 65 ou mais passar a 20.000 e os outros ficarem iguais, qual razão resulta?","version":3}},{"id":"d1434000-0000-4000-8000-000000000068","label":"G68","beforeHash":"98d4f7582d39534958b567a83dc2e46c082d9ace9160abd9217bba3dbc341737","afterHash":"61c5de96a8cb302f4ec8cf6028a38a256e9c0dcb79c4862fc63fa564fbbf0341","patch":{"statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. Nas dez horas do período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. Potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nPor que esses valores não demonstram disponibilidade de 55 MW em qualquer hora?","version":3}},{"id":"d1434000-0000-4000-8000-000000000073","label":"G73","beforeHash":"d56cc10c97902371ea673bcf74944dd1f633a15e11477526c5590f9eac445580","afterHash":"d13add92c190d6b1adab7aafb1cffdb900fec65eb349cbd68380e85440f6791a","patch":{"statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. Saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nUma sequência de dois meses com saldos −60 e −20 mm representa que saldo acumulado simplificado?","version":3}},{"id":"d1434000-0000-4000-8000-000000000077","label":"G77","beforeHash":"916290f4ad5d52165c08afc7bf1aa8592f410f9ab75ed9634a8b03e3ec849ac4","afterHash":"29ca479bb4ac8df96b5415c1a08fc64043d8ad2901783da4210f01b5f5755136","patch":{"statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. Considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nEm um modelo esférico da Terra, por que 20° de longitude representam menor distância sobre o paralelo de 60° do que sobre o equador?","version":4}},{"id":"d1434000-0000-4000-8000-000000000078","label":"G78","beforeHash":"9aba2d361dddd2df0acc58dbfcd371a98525ae254b1b27b5c7e7dfd83fce9eb5","afterHash":"daabbe441b9f3b07ff17dd10b63ddb1dee406921fc77c6e83b73f5a51dfbf85e","patch":{"statement":"Em uma região fictícia, 12.000 pessoas estão ocupadas, 3.000 não estão ocupadas mas procuram trabalho e estão disponíveis, e 5.000 estão fora desse grupo de participação. Força de trabalho = ocupados + pessoas que procuram e estão disponíveis; taxa de desocupação = desocupados/força de trabalho × 100.\n\nQue informação complementa a taxa para avaliar melhoria das condições de trabalho?","version":3}},{"id":"d1434000-0000-4000-8000-000000000085","label":"G85","beforeHash":"b72ca8bb2247cf4e4defdc28f273e8ca17b26cb9c32bccfc6d78d1f04506991c","afterHash":"880884ed822ef01d3610dfa81f08a07a9605b6111beb92b107951fca3556c815","patch":{"statement":"A população de uma região é dividida em 0–14 anos: 30.000; 15–64 anos: 60.000; 65 anos ou mais: 10.000. A razão de dependência demográfica é (população de 0–14 mais população de 65 ou mais)/população de 15–64 × 100. O indicador não mede diretamente quem trabalha ou recebe renda.\n\nQue informação complementa esses números para planejar serviços?","version":3}},{"id":"d1434000-0000-4000-8000-000000000086","label":"G86","beforeHash":"9205f53536a96a6157d23c92f23021be48d646b258187fb5d10a5da03eccb045","afterHash":"ef5e4694fd53bf6faa3297591d8f0c384d55af970905efc2e193d073ff095863","patch":{"options":["B tem maior produtividade, mas A tem maior lucro total: R$ 2,4 milhões contra R$ 0,5 milhão.","B tem maior produtividade e maior lucro total, pois produz mais por hectare.","As duas têm o mesmo lucro por tonelada, pois o preço de venda é igual.","A tem maior produtividade e maior lucro total, pois produz mais toneladas.","A tem maior lucro total, mas B tem lucro de R$ 6,5 milhões, pois seu lucro é o total de toneladas multiplicado pelo custo por tonelada."],"version":4}},{"id":"d1434000-0000-4000-8000-000000000088","label":"G88","beforeHash":"6983a90d6a1d7395bc90b2f04b043287df94ba80d4312f73152972f8c2cac94b","afterHash":"94d8a3383952142db14e08cc152eff87099f3358d1e995898974a2316a56e284","patch":{"statement":"Uma região tem 100 MW instalados em painéis solares e 100 MW em turbinas eólicas. Nas dez horas do período observado, os fatores de capacidade médios foram 20% e 35%, respectivamente. Potência média = potência instalada × fator de capacidade. As condições não garantem produção constante em cada hora.\n\nQual informação melhora o planejamento do atendimento contínuo da demanda?","version":3}},{"id":"d1434000-0000-4000-8000-000000000093","label":"G93","beforeHash":"d58e51020abb04b0833970ec8920f4d5fcc1eb8b648c8eecd13b4daed8ec9ac1","afterHash":"daf72b7505895ead7a1b91c7a8375c5c0a035fd67fb8d9cb59f1eb5f5da30edb","patch":{"statement":"Em uma localidade, janeiro recebe 180 mm de chuva e apresenta demanda evaporativa de 120 mm; julho recebe 40 mm e demanda 100 mm. Saldo mensal simplificado = chuva − demanda. Não se consideram estoques do solo, irrigação nem fluxos subterrâneos.\n\nQual comparação distingue clima de uma observação meteorológica isolada?","version":3}},{"id":"d1434000-0000-4000-8000-000000000097","label":"G97","beforeHash":"5929382dc0e714dcc41f949161731433acc58b816977f50f6f58c19e5c505f41","afterHash":"9c647fa9c97a9aa212ab1ef6f212b3bf011bbe13593f9b19a1617a555cc1e6a6","patch":{"statement":"Um mapa esquemático marca A em 20° S e 40° W; B em 20° N e 40° W; C em 20° S e 20° W. Considere latitude e longitude como coordenadas angulares, sem usar seus valores diretamente como quilômetros. Todos os pontos usam a mesma referência geográfica.\n\nQue informação falta para determinar a distância real precisa entre os pontos usando apenas o desenho esquemático?","version":3}}]'::jsonb; c jsonb; current_content jsonb; current_hash text;
begin
 perform pg_advisory_xact_lock(hashtextextended('editorial_catalog_stage46',46));
 perform 1 from public.questions where id in(select (value->>'id')::uuid from jsonb_array_elements(changes)) order by id for update;
 perform 1 from public.question_answers where question_id in(select (value->>'id')::uuid from jsonb_array_elements(changes)) order by question_id for update;
 for c in select value from jsonb_array_elements(changes) loop
  select jsonb_build_object('subject',q.subject,'topic',q.topic,'difficulty',q.difficulty,'statement',q.statement,
 'options',jsonb_build_array(q.option_a,q.option_b,q.option_c,q.option_d,q.option_e),'correctAnswer',a.correct_answer,
 'explanation',a.explanation,'status',q.status,'version',q.version,'targetExam',q.target_exam) into current_content from public.questions q left join public.question_answers a on a.question_id=q.id where q.id=(c->>'id')::uuid;
  current_hash:=encode(sha256(convert_to(current_content::text,'UTF8')),'hex');
  if current_hash is null or (current_hash<>c->>'beforeHash' and current_hash<>c->>'afterHash') then raise exception 'stage46_content_diverged: %',c->>'label';end if;
  if current_hash<>c->>'afterHash' and (
   exists(select 1 from private.practice_attempts where question_id=(c->>'id')::uuid)
   or exists(select 1 from private.guest_quiz_questions where question_id=(c->>'id')::uuid)
   or exists(select 1 from private.simulation_attempts where snapshots @> jsonb_build_array(jsonb_build_object('id',c->>'id')))) then
   raise exception 'stage46_content_used: %',c->>'label';
  end if;
 end loop;
 for c in select value from jsonb_array_elements(changes) loop
  select jsonb_build_object('subject',q.subject,'topic',q.topic,'difficulty',q.difficulty,'statement',q.statement,
 'options',jsonb_build_array(q.option_a,q.option_b,q.option_c,q.option_d,q.option_e),'correctAnswer',a.correct_answer,
 'explanation',a.explanation,'status',q.status,'version',q.version,'targetExam',q.target_exam) into current_content from public.questions q left join public.question_answers a on a.question_id=q.id where q.id=(c->>'id')::uuid;
  if encode(sha256(convert_to(current_content::text,'UTF8')),'hex')=c->>'afterHash' then continue;end if;
  update public.questions set statement=coalesce(c->'patch'->>'statement',statement),topic=coalesce(c->'patch'->>'topic',topic),difficulty=coalesce(c->'patch'->>'difficulty',difficulty),
   option_a=coalesce(c->'patch'->'options'->>0,option_a),option_b=coalesce(c->'patch'->'options'->>1,option_b),option_c=coalesce(c->'patch'->'options'->>2,option_c),
   option_d=coalesce(c->'patch'->'options'->>3,option_d),option_e=coalesce(c->'patch'->'options'->>4,option_e),
   target_exam=coalesce(c->'patch'->>'targetExam',target_exam),version=(c->'patch'->>'version')::int where id=(c->>'id')::uuid;
  update public.question_answers set correct_answer=coalesce(c->'patch'->>'correctAnswer',correct_answer),explanation=coalesce(c->'patch'->>'explanation',explanation) where question_id=(c->>'id')::uuid;
  select jsonb_build_object('subject',q.subject,'topic',q.topic,'difficulty',q.difficulty,'statement',q.statement,
 'options',jsonb_build_array(q.option_a,q.option_b,q.option_c,q.option_d,q.option_e),'correctAnswer',a.correct_answer,
 'explanation',a.explanation,'status',q.status,'version',q.version,'targetExam',q.target_exam) into current_content from public.questions q left join public.question_answers a on a.question_id=q.id where q.id=(c->>'id')::uuid;
  if encode(sha256(convert_to(current_content::text,'UTF8')),'hex')<>c->>'afterHash' then raise exception 'stage46_after_mismatch: %',c->>'label';end if;
 end loop;
end $stage46$;
